Prop.CDATA:
function UpdateItemSiteCellCustom(n, c) {    var activeRow = c.cell.row;
    var receiptNbr = px_alls['edReceiptNbr'].getValue();
    var bulkTransfer = px_alls['CstPXCheckBox1'].getValue();
    var sCell = activeRow.getCell('Selected');
    var qCell = activeRow.getCell('QtySelected');
    var origReceiptQty = activeRow.getCell('UsrActualQty').getValue();
    var q = activeRow.getCell('QtyOnHand');
    if (sCell == c.cell) {
        if (sCell.getValue() == true)
            if (receiptNbr != null && bulkTransfer) {
                qCell.setValue(origReceiptQty)
            }
            else {
                qCell.setValue(q.getValue());
            }
        else
            qCell.setValue('0');
    }
    if (qCell == c.cell) {
        if (qCell.getValue() == '0')
            sCell.setValue(false);
        else
            sCell.setValue(true);
    }
}
